window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0cf680977158199a"]={"versions": [{"id": "FIG-0cf680977158199a", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (Work-Product-Flow) zur Erzeugung von ladbaren BSW-Konfigurationsdaten (Generate BSW Configuration Data Loadable). Das Diagramm stellt den Datenfluss von Eingangs-Work-Products über eine methodische Aktivität hin zu den resultierenden Ausgangs-Work-Products dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Input Work Product</strong>: Unbenanntes Dokumenten-Artefakt (dargestellt als Dateisymbol mit umgeknickter Ecke), eingehend über eine gerichtete Kante mit dem Stereotyp <code>«input»</code> und der Multiplizität <code>1</code>.\n</li><li><strong>Aktivität</strong>: <code>Generate BSW Configuration Data</code> (dargestellt als gelber Prozessblock mit nach rechts weisender Pfeilspitze).\n</li><li><strong>Output Work Product</strong>: Unbenanntes Dokumenten-Artefakt (dargestellt als Dateisymbol mit umgeknickter Ecke), ausgehend über eine gerichtete Kante mit dem Stereotyp <code>«output»</code> und der Multiplizität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein einzelnes Eingangs-Artefakt (<code>«input»</code>, Multiplizität 1) wird der Aktivität <code>Generate BSW Configuration Data</code> bereitgestellt.\n</li><li>Die Aktivität verarbeitet die Konfiguration und transformiert die Eingangsdaten in das Zielformat.\n</li><li>Als Resultat wird genau ein Ausgangs-Artefakt (<code>«output»</code>, Multiplizität 1) erzeugt (ladbare BSW-Konfigurationsdaten).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung der Aktivität <code>Generate BSW Configuration Data</code> erfordert exakt ein Eingangs-Work-Product und liefert deterministisch genau ein Ausgangs-Work-Product (Kardinalitäten jeweils 1). In Generierungs- und Build-Pipelines ist sicherzustellen, dass die Werkzeugkette das Eingangsartefakt vollständig validiert, bevor die Erzeugung der binären/ladbaren BSW-Konfigurationsdaten angestoßen wird.</p>"}, {"id": "FIG-5783cb6b2b76aca3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (Work-Product-Flow) zur Erzeugung von ladbaren BSW-Konfigurationsdaten (Generate BSW Configuration Data Loadable). Das Diagramm stellt den Datenfluss von Eingangs-Work-Products über eine methodische Aktivität hin zu den resultierenden Ausgangs-Work-Products dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Input Work Product</strong>: Unbenanntes Dokumenten-Artefakt (dargestellt als Dateisymbol mit umgeknickter Ecke), eingehend über eine gerichtete Kante mit dem Stereotyp <code>«input»</code> und der Multiplizität <code>1</code>.\n</li><li><strong>Aktivität</strong>: <code>Generate BSW Configuration Data</code> (dargestellt als gelber Prozessblock mit nach rechts weisender Pfeilspitze).\n</li><li><strong>Output Work Product</strong>: Unbenanntes Dokumenten-Artefakt (dargestellt als Dateisymbol mit umgeknickter Ecke), ausgehend über eine gerichtete Kante mit dem Stereotyp <code>«output»</code> und der Multiplizität <code>1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ein einzelnes Eingangs-Artefakt (<code>«input»</code>, Multiplizität 1) wird der Aktivität <code>Generate BSW Configuration Data</code> bereitgestellt.\n</li><li>Die Aktivität verarbeitet die Konfiguration und transformiert die Eingangsdaten in das Zielformat.\n</li><li>Als Resultat wird genau ein Ausgangs-Artefakt (<code>«output»</code>, Multiplizität 1) erzeugt (ladbare BSW-Konfigurationsdaten).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung der Aktivität <code>Generate BSW Configuration Data</code> erfordert exakt ein Eingangs-Work-Product und liefert deterministisch genau ein Ausgangs-Work-Product (Kardinalitäten jeweils 1). In Generierungs- und Build-Pipelines ist sicherzustellen, dass die Werkzeugkette das Eingangsartefakt vollständig validiert, bevor die Erzeugung der binären/ladbaren BSW-Konfigurationsdaten angestoßen wird.</p>"}], "trans": [{"from": "FIG-0cf680977158199a", "to": "FIG-5783cb6b2b76aca3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
